-- CORUM Eurion T2 2026 source-page allocations: geography 8 regions and sector 5,
-- 100% in each group. No inferred values for scanned Origin or XL charts.
CREATE TABLE IF NOT EXISTS maximus_agents.scpi_candidate_allocations (
 scpi_slug text NOT NULL REFERENCES maximus_agents.scpi_universe(scpi_slug),
 source_period text NOT NULL,
 allocation_type text NOT NULL CHECK(allocation_type IN('sector','geography')),
 label text NOT NULL,
 pct numeric(8,3) NOT NULL CHECK(pct>=0 AND pct<=100),
 source_url text NOT NULL, source_sha256 text NOT NULL CHECK(source_sha256~'^[0-9a-f]{64}$'),
 source_page integer NOT NULL CHECK(source_page BETWEEN 1 AND 250),
 evidence_excerpt text NOT NULL CHECK(length(evidence_excerpt)>80),
 qa_status text NOT NULL DEFAULT 'qa_pass' CHECK(qa_status IN('qa_pass','needs_review')),
 checked_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(scpi_slug,source_period,allocation_type,label)
);
REVOKE ALL ON maximus_agents.scpi_candidate_allocations FROM PUBLIC,anon,authenticated;
