INSERT INTO maximus_agents.scpi_candidate_allocations
(scpi_slug,source_period,allocation_type,label,pct,source_url,source_sha256,source_page,evidence_excerpt)
SELECT o.slug,o.period,o.kind,o.label,o.pct::numeric,o.url,o.hash,o.page::integer,o.evidence
FROM observed o JOIN maximus_agents.scpi_candidate_pdf_validation d
 ON d.scpi_slug=o.slug AND d.source_period=o.period AND d.document_kind='quarterly_bulletin'
 AND d.pdf_sha256=o.hash AND d.source_url=o.url AND d.document_identity_verified
WHERE o.page::int BETWEEN 1 AND d.page_count
AND (SELECT sum(pct::numeric) FROM observed WHERE slug=o.slug AND period=o.period AND kind=o.kind)=100
ON CONFLICT(scpi_slug,source_period,allocation_type,label) DO NOTHING;
